#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Setup for docs/superpowers/specs/2026-09-30-mobile-sign-in-design.md
# ("Setup only Byron can do"). Run from the repo root:
#   bash scripts/setup-mobile-sign-in.sh
# Client IDs are public (they ship in the app), so they go in the mobile
# .env.local; no client secret is ever written to disk.

cd "$(dirname "$0")/.."
ENV_FILE=packages/mobile/.env.local
REF=napjjvnriegcszcvkysj
SB="https://supabase.com/dashboard/project/$REF"
BUNDLE=com.splatconnect.mobile

copy() { # copy FILE: put a template on the clipboard when pbcopy exists
  if command -v pbcopy >/dev/null 2>&1; then pbcopy < "$1"; note "copied $1 to the clipboard"
  else note "open $1 and copy its contents"; fi
}

TOTAL_STAGES=10

banner "SPLAT mobile sign-in setup"

stage "Supabase: email templates with a 6-digit code"
say "Each email keeps its link (web still uses it) and gains the code the app asks for."
open_url "$SB/auth/templates"
step "Confirm signup → Subject: Your SPLAT Connect code"
copy supabase/templates/confirmation.html
step "Replace the Message body with the clipboard, then Save."
pause
step "Magic Link → Subject: Your SPLAT Connect sign-in code"
copy supabase/templates/magic_link.html
step "Replace the Message body with the clipboard, then Save."
pause
step "Reset Password → Subject: Reset your SPLAT Connect password"
copy supabase/templates/recovery.html
step "Replace the Message body with the clipboard, then Save."
pause

stage "Supabase: code length"
open_url "$SB/auth/providers"
step "Open the Email provider."
step "Email OTP Length must be 6 and Email OTP Expiration 3600 seconds. Save if you changed either."
pause

stage "Apple: turn on Sign in with Apple"
warn "Needs the paid Apple Developer Program. A free personal team cannot hold this capability."
if confirm "Is team 847BXN928Z a paid Apple Developer Program membership?"; then
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Open the App ID $BUNDLE (create it if it is missing)."
  step "Tick 'Sign In with Apple', keep 'Enable as a primary App ID', then Save."
  pause
  APPLE=1
else
  APPLE=0
  SKIPPED+=("Sign in with Apple: join the Apple Developer Program, then re-run this wizard")
  note "Apple stays off: the app will show Google and email only."
fi

stage "Apple: email relay for Hide My Email users"
say "Apple forwards mail to private relay addresses only from domains you register."
warn "Supabase's built-in sender (mail.app.supabase.io) cannot be registered. This needs custom SMTP"
warn "(Supabase → Auth → SMTP settings) on a domain you own, with SPF and DKIM."
if [[ "$APPLE" == 1 ]] && confirm "Is custom SMTP on your own domain already set up in Supabase?"; then
  open_url "https://developer.apple.com/account/resources/services/configure"
  step "Sign in with Apple for Email Communication → Configure → add the sending domain and address."
  step "Apple checks SPF; it shows a green tick when it passes."
  pause
else
  SKIPPED+=("Apple email relay: set up custom SMTP, then register its domain (codes won't reach Hide My Email users until then)")
fi

stage "Google: consent screen and branding"
open_url "https://console.cloud.google.com/auth/branding"
step "App name: SPLAT Connect. Support email: yours. Upload the SPLAT logo."
step "App home page and privacy policy: your web URL and <web URL>/privacy."
step "Authorised domains: the web domain and $REF.supabase.co."
step "Audience: External, then publish. Start brand verification if Google offers it."
pause

stage "Google: Web client (Supabase verifies tokens with it)"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: SPLAT Supabase."
step "Authorised redirect URI: https://$REF.supabase.co/auth/v1/callback"
step "Create. Keep the Client secret handy for stage 9; it is not saved anywhere by this script."
ask EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID "Paste the Web Client ID (ends .apps.googleusercontent.com):"
write_env EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID "$EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID"

stage "Google: iOS client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: iOS. Bundle ID: $BUNDLE. Team ID: 847BXN928Z."
ask EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID "Paste the iOS Client ID:"
write_env EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID "$EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID"

stage "Google: Android client"
KS=packages/mobile/android/app/debug.keystore
[[ -f "$KS" ]] || KS="$HOME/.android/debug.keystore"
if [[ -f "$KS" ]] && command -v keytool >/dev/null 2>&1; then
  say "Debug SHA-1 ($KS):"
  keytool -list -v -keystore "$KS" -alias androiddebugkey -storepass android 2>/dev/null | grep 'SHA1:' | sed 's/^/    /' || true
else
  note "No debug keystore yet; run 'npx expo prebuild' in packages/mobile, then re-run this stage."
fi
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Android. Package name: $BUNDLE. SHA-1: the value above. Create."
note "Android needs no ID in the app: it signs in with the Web client ID."
SKIPPED+=("Google Android release client: add the Play App Signing SHA-1 once the app is on Play")
pause

stage "Supabase: enable Apple and Google"
open_url "$SB/auth/providers"
if [[ "$APPLE" == 1 ]]; then
  step "Apple → Enable. Client IDs: $BUNDLE. Save (no secret key is needed for native sign-in)."
fi
step "Google → Enable."
step "Client ID: $EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID"
step "Client Secret: the Web client's secret from stage 6."
step "Authorized Client IDs: $EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID,$EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID"
step "Skip nonce checks: ON (iOS Google tokens carry a nonce the app cannot supply). Save."
pause

stage "Build the phone app with both providers"
write_env EXPO_PUBLIC_APPLE_SIGN_IN "$APPLE"
say "prebuild --clean regenerates packages/mobile/ios and android from app.config.ts."
if confirm "Delete and regenerate the native folders, then build to the connected iPhone now?"; then
  (cd packages/mobile && npx expo prebuild --clean && npx expo run:ios --device)
else
  SKIPPED+=("cd packages/mobile && npx expo prebuild --clean && npx expo run:ios --device")
fi

finish
